/**
 * @suppress
 */
public object FfiConverterTypeDengonNode: FfiConverter<DengonNode, Pointer> {

    override fun lower(value: DengonNode): Pointer {
        return value.uniffiClonePointer()
    }

    override fun lift(value: Pointer): DengonNode {
        return DengonNode(value)
    }

    override fun read(buf: ByteBuffer): DengonNode {
        // The Rust code always writes pointers as 8 bytes, and will
        // fail to compile if they don't fit.
        return lift(Pointer(buf.getLong()))
    }

    override fun allocationSize(value: DengonNode) = 8UL

    override fun write(value: DengonNode, buf: ByteBuffer) {
        // The Rust code always expects pointers written as 8 bytes,
        // and will fail to compile if they don't fit.
        buf.putLong(Pointer.nativeValue(lower(value)))
    }
}



