sealed class DengonException(message: String): kotlin.Exception(message) {
        
        class UnknownPeer(message: String) : DengonException(message)
        
        class NotConnected(message: String) : DengonException(message)
        
        class Internal(message: String) : DengonException(message)
        

    companion object ErrorHandler : UniffiRustCallStatusErrorHandler<DengonException> {
        override fun lift(error_buf: RustBuffer.ByValue): DengonException = FfiConverterTypeDengonError.lift(error_buf)
    }
}

/**
 * @suppress
 */
public object FfiConverterTypeDengonError : FfiConverterRustBuffer<DengonException> {
    override fun read(buf: ByteBuffer): DengonException {
        
            return when(buf.getInt()) {
            1 -> DengonException.UnknownPeer(FfiConverterString.read(buf))
            2 -> DengonException.NotConnected(FfiConverterString.read(buf))
            3 -> DengonException.Internal(FfiConverterString.read(buf))
            else -> throw RuntimeException("invalid error enum value, something is very wrong!!")
        }
        
    }

    override fun allocationSize(value: DengonException): ULong {
        return 4UL
    }

    override fun write(value: DengonException, buf: ByteBuffer) {
        when(value) {
            is DengonException.UnknownPeer -> {
                buf.putInt(1)
                Unit
            }
            is DengonException.NotConnected -> {
                buf.putInt(2)
                Unit
            }
            is DengonException.Internal -> {
                buf.putInt(3)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }

}




enum class MessageStatus {
    
    QUEUED,
    IN_FLIGHT,
    DELIVERED,
    READ,
    EXPIRED,
    CANCELLED;
    companion object
}


/**
 * @suppress
 */
public object FfiConverterTypeMessageStatus: FfiConverterRustBuffer<MessageStatus> {
    override fun read(buf: ByteBuffer) = try {
        MessageStatus.values()[buf.getInt() - 1]
    } catch (e: IndexOutOfBoundsException) {
        throw RuntimeException("invalid enum value, something is very wrong!!", e)
    }

    override fun allocationSize(value: MessageStatus) = 4UL

    override fun write(value: MessageStatus, buf: ByteBuffer) {
        buf.putInt(value.ordinal + 1)
    }
}





sealed class NodeEvent {
    
    data class MessageReceived(
        val `message`: Message) : NodeEvent() {
        companion object
    }
    
    data class StatusChanged(
        val `msgUuid`: kotlin.String, 
        val `status`: MessageStatus) : NodeEvent() {
        companion object
    }
    
    data class PeerConnected(
        val `peerId`: kotlin.String) : NodeEvent() {
        companion object
    }
    
    data class PeerDisconnected(
        val `peerId`: kotlin.String) : NodeEvent() {
        companion object
    }
    

    
    companion object
}

/**
 * @suppress
 */
public object FfiConverterTypeNodeEvent : FfiConverterRustBuffer<NodeEvent>{
    override fun read(buf: ByteBuffer): NodeEvent {
        return when(buf.getInt()) {
            1 -> NodeEvent.MessageReceived(
                FfiConverterTypeMessage.read(buf),
                )
            2 -> NodeEvent.StatusChanged(
                FfiConverterString.read(buf),
                FfiConverterTypeMessageStatus.read(buf),
                )
            3 -> NodeEvent.PeerConnected(
                FfiConverterString.read(buf),
                )
            4 -> NodeEvent.PeerDisconnected(
                FfiConverterString.read(buf),
                )
            else -> throw RuntimeException("invalid enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: NodeEvent) = when(value) {
        is NodeEvent.MessageReceived -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterTypeMessage.allocationSize(value.`message`)
            )
        }
        is NodeEvent.StatusChanged -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterString.allocationSize(value.`msgUuid`)
                + FfiConverterTypeMessageStatus.allocationSize(value.`status`)
            )
        }
        is NodeEvent.PeerConnected -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterString.allocationSize(value.`peerId`)
            )
        }
        is NodeEvent.PeerDisconnected -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterString.allocationSize(value.`peerId`)
            )
        }
    }

    override fun write(value: NodeEvent, buf: ByteBuffer) {
        when(value) {
            is NodeEvent.MessageReceived -> {
                buf.putInt(1)
                FfiConverterTypeMessage.write(value.`message`, buf)
                Unit
            }
            is NodeEvent.StatusChanged -> {
                buf.putInt(2)
                FfiConverterString.write(value.`msgUuid`, buf)
                FfiConverterTypeMessageStatus.write(value.`status`, buf)
                Unit
            }
            is NodeEvent.PeerConnected -> {
                buf.putInt(3)
                FfiConverterString.write(value.`peerId`, buf)
